<div class="card form"><h1>🔐 Login</h1><form id="login"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><label>Language</label><select name="language"><option value="en">English</option><option value="ar">العربية</option></select><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><button class="btn">Login</button></form><div id="msg"></div><p>No account? <a href="index.php?page=register">Register</a></p></div><script>(function(){document.getElementById('login').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);f.append('action','login');try{let r=await post('backend/api/auth.php',f);location.href='index.php?page='+(r.role==='parent'?'parent':r.role==='tutor'?'tutor':r.role==='admin'?'admin':'dashboard')}catch(x){document.getElementById('msg').innerHTML='<div class="notice error">'+escapeHTML(x.message)+'</div>'}}})()</script>
